SUBROUTINE pTC2rhoY (p, T, C, RHO, Y)
IMPLICIT DOUBLE PRECISION (A-H, O-Z), INTEGER (I-N)
DIMENSION Y(*), C(*), WT(  53)
DATA SMALL/1D-50/

CALL SKWT (WT)
WM1 = 0.D0
WM2 = 0.D0
DO K=1,  53
  WM1 = WM1 + C(K) 
  WM2 = WM2 + C(K)*WT(K) 
ENDDO
WM = WM2/max(WM1,1.D-50) 
RHO = P*WM/(T*8.314510D7)
!
DO K=1,  53
  Y(K) = WT(K) * C(K) / RHO
ENDDO


END


