DWDM = WFDM -WBDM
A(   5,   2) = A(   5,   2) +0.100000000000D+01 * (  -1) * DWDM
A(   5,   7) = A(   5,   7) +0.100000000000D+01 * (  -1) * DWDM
A(   5,  10) = A(   5,  10) +0.500000000000D+01 * (  -1) * DWDM
A(   5,  18) = A(   5,  18) +0.500000000000D+00 * (  -1) * DWDM
A(   5,  19) = A(   5,  19) +0.100000000000D+01 * (  -1) * DWDM
A(   5,  28) = A(   5,  28) +0.200000000000D+01 * (  -1) * DWDM
DM(   4) = DM(   4)   -1* DWDM
A(   3,   2) = A(   3,   2) +0.100000000000D+01 * (  -1) * DWDM
A(   3,   7) = A(   3,   7) +0.100000000000D+01 * (  -1) * DWDM
A(   3,  10) = A(   3,  10) +0.500000000000D+01 * (  -1) * DWDM
A(   3,  18) = A(   3,  18) +0.500000000000D+00 * (  -1) * DWDM
A(   3,  19) = A(   3,  19) +0.100000000000D+01 * (  -1) * DWDM
A(   3,  28) = A(   3,  28) +0.200000000000D+01 * (  -1) * DWDM
DM(   2) = DM(   2)   -1* DWDM
A(   4,   2) = A(   4,   2) +0.100000000000D+01 * (  +1) * DWDM
A(   4,   7) = A(   4,   7) +0.100000000000D+01 * (  +1) * DWDM
A(   4,  10) = A(   4,  10) +0.500000000000D+01 * (  +1) * DWDM
A(   4,  18) = A(   4,  18) +0.500000000000D+00 * (  +1) * DWDM
A(   4,  19) = A(   4,  19) +0.100000000000D+01 * (  +1) * DWDM
A(   4,  28) = A(   4,  28) +0.200000000000D+01 * (  +1) * DWDM
DM(   3) = DM(   3)   +1* DWDM

A(   1,   1) = A(   1,   1) &
 + DTDT(   1) * HML(   1)  + CPML(   1) * WK(   1) &
 + DTDT(   2) * HML(   2)  + CPML(   2) * WK(   2) &
 + DTDT(   3) * HML(   3)  + CPML(   3) * WK(   3) &
 + DTDT(   4) * HML(   4)  + CPML(   4) * WK(   4) &
 + DTDT(   5) * HML(   5)  + CPML(   5) * WK(   5) &
 + DTDT(   6) * HML(   6)  + CPML(   6) * WK(   6) &
 + DTDT(   7) * HML(   7)  + CPML(   7) * WK(   7) &
 + DTDT(   8) * HML(   8)  + CPML(   8) * WK(   8) &
 + DTDT(   9) * HML(   9)  + CPML(   9) * WK(   9) &
 + DTDT(  10) * HML(  10)  + CPML(  10) * WK(  10) &
 + DTDT(  11) * HML(  11)  + CPML(  11) * WK(  11) &
 + DTDT(  12) * HML(  12)  + CPML(  12) * WK(  12) &
 + DTDT(  13) * HML(  13)  + CPML(  13) * WK(  13) &
 + DTDT(  14) * HML(  14)  + CPML(  14) * WK(  14) &
 + DTDT(  15) * HML(  15)  + CPML(  15) * WK(  15) &
 + DTDT(  16) * HML(  16)  + CPML(  16) * WK(  16) &
 + DTDT(  17) * HML(  17)  + CPML(  17) * WK(  17) &
 + DTDT(  18) * HML(  18)  + CPML(  18) * WK(  18) &
 + DTDT(  19) * HML(  19)  + CPML(  19) * WK(  19) &
 + DTDT(  20) * HML(  20)  + CPML(  20) * WK(  20) &
 + DTDT(  21) * HML(  21)  + CPML(  21) * WK(  21) &
 + DTDT(  22) * HML(  22)  + CPML(  22) * WK(  22) &
 + DTDT(  23) * HML(  23)  + CPML(  23) * WK(  23) &
 + DTDT(  24) * HML(  24)  + CPML(  24) * WK(  24) &
 + DTDT(  25) * HML(  25)  + CPML(  25) * WK(  25) &
 + DTDT(  26) * HML(  26)  + CPML(  26) * WK(  26) &
 + DTDT(  27) * HML(  27)  + CPML(  27) * WK(  27) &
 + DTDT(  28) * HML(  28)  + CPML(  28) * WK(  28) &
 + DTDT(  29) * HML(  29)  + CPML(  29) * WK(  29) &
 + DTDT(  30) * HML(  30)  + CPML(  30) * WK(  30) &
 + DTDT(  31) * HML(  31)  + CPML(  31) * WK(  31) &
 + DTDT(  32) * HML(  32)  + CPML(  32) * WK(  32) &
