SUBROUTINE DMDC(A, KK, DM, HML, WT, RHO, CPB)
IMPLICIT DOUBLE PRECISION (A-H, O-Z), INTEGER (I-N)
DIMENSION A(KK+1,*), DM(*), HML(*), WT(*)

DO K=1,  53
  A(k+1,1) = A(k+1,1) * WT(K) / RHO
ENDDO

DO N=2,  54
A(   2, N) = A(   2, N) + DM(   1)
A(   3, N) = A(   3, N) + DM(   2)
A(   4, N) = A(   4, N) + DM(   3)
A(   5, N) = A(   5, N) + DM(   4)
A(   6, N) = A(   6, N) + DM(   5)
A(   7, N) = A(   7, N) + DM(   6)
A(   8, N) = A(   8, N) + DM(   7)
A(   9, N) = A(   9, N) + DM(   8)
A(  10, N) = A(  10, N) + DM(   9)
A(  11, N) = A(  11, N) + DM(  10)
A(  12, N) = A(  12, N) + DM(  11)
A(  14, N) = A(  14, N) + DM(  13)
A(  15, N) = A(  15, N) + DM(  14)
A(  16, N) = A(  16, N) + DM(  15)
A(  17, N) = A(  17, N) + DM(  16)
A(  18, N) = A(  18, N) + DM(  17)
A(  19, N) = A(  19, N) + DM(  18)
A(  20, N) = A(  20, N) + DM(  19)
A(  21, N) = A(  21, N) + DM(  20)
A(  22, N) = A(  22, N) + DM(  21)
A(  23, N) = A(  23, N) + DM(  22)
A(  24, N) = A(  24, N) + DM(  23)
A(  25, N) = A(  25, N) + DM(  24)
A(  26, N) = A(  26, N) + DM(  25)
A(  27, N) = A(  27, N) + DM(  26)
A(  28, N) = A(  28, N) + DM(  27)
A(  29, N) = A(  29, N) + DM(  28)
A(  30, N) = A(  30, N) + DM(  29)
A(  32, N) = A(  32, N) + DM(  31)
A(  33, N) = A(  33, N) + DM(  32)
A(  36, N) = A(  36, N) + DM(  35)
A(  37, N) = A(  37, N) + DM(  36)
A(  38, N) = A(  38, N) + DM(  37)
A(  39, N) = A(  39, N) + DM(  38)
A(  40, N) = A(  40, N) + DM(  39)
A(  41, N) = A(  41, N) + DM(  40)
A(  42, N) = A(  42, N) + DM(  41)
A(  43, N) = A(  43, N) + DM(  42)
A(  44, N) = A(  44, N) + DM(  43)
A(  47, N) = A(  47, N) + DM(  46)
A(  48, N) = A(  48, N) + DM(  47)
A(  49, N) = A(  49, N) + DM(  48)
A(  51, N) = A(  51, N) + DM(  50)
A(  52, N) = A(  52, N) + DM(  51)
A(  53, N) = A(  53, N) + DM(  52)
ENDDO

DO K=1,  53
  DO K1=1,  53
    A(1,K+1) = A(1,K+1) + A(K1+1,K+1) * HML(K1) / (CPB * WT(K))
  ENDDO
ENDDO

DO K=1,  53
DO K1=1,  53
  A(K+1,K1+1) = A(K+1,K1+1) * WT(K) / WT(K1)
ENDDO
ENDDO


END

