! SUBROUTINE JAC (NEQ, T, Z, ML, MU, PD, NRPD, RPAR, IPAR)
! IMPLICIT DOUBLE PRECISION (A-H, O-Z), INTEGER (I-N)
! DOUBLE PRECISION PD, RPAR, T, Z
! COMMON /ICONS/ KK, NP, NWT, NH, NWDOT
! DIMENSION Z(NEQ), PD(NEQ,NEQ),CPML(KK),HML(KK),WT(KK),&
! G0(KK),DG(KK),C(KK),RPAR(*),IPAR(*),DM(KK),DTDT(KK+1),DTDC(KK+1),WK(KK)
! CALL pTY2rhoC (RPAR(NP), Z(1), Z(2), RHO, C)
! CTOT = 0.D0
! DO N=1,  53
  ! CTOT = CTOT +C(N)
! ENDDO
! !
! CALL GDG1(Z(1), G0, DG)
! !
! CALL CKRHOY (RPAR(NP), Z(1), Z(2), IPAR, RPAR, RHO)
! !
! CALL CKCPBS (Z(1), Z(2), IPAR, RPAR, CPB)
! !
! CALL SKWT (WT)
! !
! CALL SKCPML  (Z(1), CPML)
! !
! CALL SKHML  (Z(1), HML)
! !
! CALL AJ1(Z(1), C, PD, KK, G0, DG, DM, CTOT, WT, RHO, CPB, CPML, HML)
! !
! CALL DMDC(PD, KK, DM, HML, WT, RHO, CPB)

! END

SUBROUTINE JAC_OF_Y (KK, p, T, Y, PD_OF)
IMPLICIT DOUBLE PRECISION (A-H, O-Z), INTEGER (I-N)
DIMENSION Y(KK), PD(KK+1,KK+1),CPML(KK),HML(KK),WT(KK),&
G0(KK),DG(KK),C(KK),DM(KK),PD_OF(0:(KK+1)*(KK+1))
!
DO k1 = 0, KK
  DO k2 = 0, KK
    PD(k1+1,k2+1) = 0.d0
  ENDDO
ENDDO
DO N=1, KK
  CPML(N) = 0.D0
  HML(N) = 0.D0
  WT(N) = 0.D0
  G0(N) = 0.D0
  DG(N) = 0.D0
  C(N) = 0.D0
  DM(N) = 0.D0
ENDDO
!
CALL pTY2rhoC_OF (p, T, Y(1), RHO, C)
CTOT = 0.D0
DO N=1, KK
  CTOT = CTOT +C(N)
ENDDO
! WT (g/mol)
CALL SKWT (WT)
! standard-state Gibbs free energy G0: ergs/mole, DG: dG0/dT
! G0 is used to calculate equilibrium constants for computing the reverse rate constants
CALL GDG1(T, G0, DG)
! CPML: ergs/(mole*K)
CALL SKCPML  (T, CPML)
! HML: ergs/mole
CALL SKHML  (T, HML)
! CPB: ergs/(g*K)
CPB = 0.D0
DO K=1, KK
  CPB = CPB + CPML(K) / WT(K) * Y(K)
ENDDO
!
CALL AJ1(T, C, PD, KK, G0, DG, DM, CTOT, WT, RHO, CPB, CPML, HML)
! DM is related to three body reactions
CALL DMDC(PD, KK, DM, HML, WT, RHO, CPB)

DO k1 = 0, KK 
  DO k2 = 0, KK
    PD_OF(k1*(KK+1)+k2) = PD(k1+1,k2+1)
  ENDDO
ENDDO

END

SUBROUTINE JAC_OF_C (KK, p, T, C, PD_OF)
IMPLICIT DOUBLE PRECISION (A-H, O-Z), INTEGER (I-N)
DIMENSION Y(KK),PD(KK+1,KK+1),CPML(KK),HML(KK),WT(KK),&
G0(KK),DG(KK),C(KK),DM(KK),PD_OF(0:(KK+1)*(KK+1))
!
DO k1 = 0, KK
  DO k2 = 0, KK
    PD(k1+1,k2+1) = 0.d0
  ENDDO
ENDDO
!
DO N=1, KK
  CPML(N) = 0.D0
  HML(N) = 0.D0
  WT(N) = 0.D0
  G0(N) = 0.D0
  DG(N) = 0.D0
  Y(N) = 0.D0
  DM(N) = 0.D0
ENDDO
!
CALL pTC2rhoY_OF (p, T, C, RHO, Y)
CTOT = 0.D0
DO N=1, KK
  CTOT = CTOT +C(N)
ENDDO
! WT (g/mol)
CALL SKWT (WT)
! standard-state Gibbs free energy G0: ergs/mole, DG: dG0/dT
! G0 is used to calculate equilibrium constants for computing the reverse rate constants
CALL GDG1(T, G0, DG)
! CPML: ergs/(mole*K)
CALL SKCPML  (T, CPML)
! HML: ergs/mole
CALL SKHML  (T, HML)
! CPB: ergs/(g*K)
CPB = 0.D0
DO K=1, KK
  CPB = CPB + CPML(K) / WT(K) * Y(K)
ENDDO
!
CALL AJ1(T, C, PD, KK, G0, DG, DM, CTOT, WT, RHO, CPB, CPML, HML)
! DM is related to three body reactions
CALL DMDC_OF_C(PD, KK, DM, HML, RHO, CPB)

DO k1 = 0, KK 
  DO k2 = 0, KK
    PD_OF(k1*(KK+1)+k2) = PD(k1+1,k2+1)
  ENDDO
ENDDO

END

SUBROUTINE omega_OF_Y(T, Y, P, KK, WDOT, DTDt)
IMPLICIT DOUBLE PRECISION (A-H, O-Z), INTEGER (I-N)
PARAMETER (EXPARG=690.776, SMALL=1.D-300)
DIMENSION Y(*), C(KK), G0(KK), WDOT(*), CPML(KK), WT(KK), HML(Kk)
DTdt = 0.d0
RHO = 0.D0
!
T2 = T*T
TLOG = LOG(T)
TI = 1.D0/T
TI2 = TI/T
PFAC = 1.218652692702276D-2/T
! G0 is used to calculate equilibrium constants for computing the reverse rate constants
CALL SKG0(T, G0)
CALL pTY2rhoC_OF (p, T, Y(1), RHO, C)
CTOT = 0.D0
DO K=1,  53
  WDOT(K) = 0.D0 ! ergs/(cm3*s)
  CTOT = CTOT +C(K)
ENDDO
!
! R   1: O+H2<=>H+OH                                       
G0_SUM = -1*G0(   7)-1*G0(   6)+1*G0(   4)+1*G0(   8)
EQINV = EXP(MIN(G0_SUM, EXPARG))
EQINV = EQINV / PFAC ** (  +0)
RF = EXP( +0.105635948790D+02  +0.270000000000D+01*TLOG &
 -0.315013633943D+04*TI)
RB = RF*EQINV
WF = RF*C(   7)**   1*C(   6)**   1
WB = RB*C(   4)**   1*C(   8)**   1
WDOT(   7) = WDOT(   7) - 1*(WF-WB)
WDOT(   6) = WDOT(   6) - 1*(WF-WB)
WDOT(   4) = WDOT(   4) + 1*(WF-WB)
WDOT(   8) = WDOT(   8) + 1*(WF-WB)

! R   2: O+HO2<=>OH+O2                                     
G0_SUM = -1*G0(   7)-1*G0(  10)+1*G0(   8)+1*G0(   5)
EQINV = EXP(MIN(G0_SUM, EXPARG))
EQINV = EQINV / PFAC ** (  +0)
RF = EXP( +0.306267533895D+02  +0.000000000000D+00*TLOG &
 -0.000000000000D+00*TI)
RB = RF*EQINV
WF = RF*C(   7)**   1*C(  10)**   1
WB = RB*C(   8)**   1*C(   5)**   1
WDOT(   7) = WDOT(   7) - 1*(WF-WB)
WDOT(  10) = WDOT(  10) - 1*(WF-WB)
WDOT(   8) = WDOT(   8) + 1*(WF-WB)
WDOT(   5) = WDOT(   5) + 1*(WF-WB)

! R   3: O+H2O2<=>OH+HO2                                   
G0_SUM = -1*G0(   7)-1*G0(  11)+1*G0(   8)+1*G0(  10)
EQINV = EXP(MIN(G0_SUM, EXPARG))
EQINV = EQINV / PFAC ** (  +0)
RF = EXP( +0.160803937838D+02  +0.200000000000D+01*TLOG &
 -0.201286667056D+04*TI)
RB = RF*EQINV
WF = RF*C(   7)**   1*C(  11)**   1
WB = RB*C(   8)**   1*C(  10)**   1
WDOT(   7) = WDOT(   7) - 1*(WF-WB)
WDOT(  11) = WDOT(  11) - 1*(WF-WB)
WDOT(   8) = WDOT(   8) + 1*(WF-WB)
WDOT(  10) = WDOT(  10) + 1*(WF-WB)

! R   4: O+CH<=>H+CO                                       
G0_SUM = -1*G0(   7)-1*G0(  13)+1*G0(   4)+1*G0(  17)
EQINV = EXP(MIN(G0_SUM, EXPARG))
EQINV = EQINV / PFAC ** (  +0)
RF = EXP( +0.316740723838D+02  +0.000000000000D+00*TLOG &
 -0.000000000000D+00*TI)
